import { accountRouter, defineApp, router, withApprovals } from "apps";
import { always } from "apps/operations/approval";
import { mcpRouter } from "apps/mcp";
import { aws, endpoint } from "./provider.js";
import { icons } from "./icon.js";

const requirements = { user: { accounts: { aws: aws.many() } }, icons };

export default defineApp(requirements, async ({ user, cache, signal }) => ({
  tools: router(
    await accountRouter(
      user?.accounts.aws ?? [],
      async (account) =>
        withApprovals(
          await mcpRouter({ url: endpoint, account, headers: account.headers(), cache, signal }),
          // AWS's API and script tools can write across services, even when a name looks like a read.
          () => always(),
        ),
      { signal },
    ),
    {
      title: "AWS",
      description: "Use AWS services through the official AWS MCP server with each person's own permissions. Every tool call asks for approval.",
      icons,
    },
  ),
}));

import { bearer, defineProvider, oauth2 } from "apps";
import { mcpHealth } from "apps/mcp";

export const endpoint = "https://aws-mcp.us-east-1.api.aws/mcp";

export const aws = defineProvider({
  name: "AWS",
  hosts: ["aws-mcp.us-east-1.api.aws"],
  auth: {
    oauth: oauth2({
      discover: endpoint,
      resource: endpoint,
      loopbackRedirectUri: "http://127.0.0.1:43119/oauth/callback",
      scopes: [],
      tokenEndpointAuthMethod: "none",
      request: ({ access_token }) => bearer(access_token),
    }),
  },
  health: (check) => mcpHealth(check, { url: endpoint, headers: check.account.headers() }),
});
